  function readBraced(text,start){let depth=0,escaped=false;for(let i=start;i<text.length;i++){const c=text[i];if(escaped){escaped=false;continue;}if(c==="\\"){escaped=true;continue;}if(c==="{")depth++;if(c==="}"){depth--;if(depth===0)return {value:text.slice(start+1,i),next:i+1};}}throw new Error("Malformed Tcl: unclosed brace");}
  function parseTopLevelTcl(text){const out={};let i=0;while(i<text.length){while(i<text.length&&/\s/.test(text[i]))i++;if(i>=text.length)break;if(text[i]==="#"){while(i<text.length&&text[i]!=="\n")i++;continue;}const ks=i;while(i<text.length&&!/\s/.test(text[i]))i++;let key=text.slice(ks,i).replace(/\ /g," ");while(i<text.length&&(text[i]===" "||text[i]==="\t"))i++;let value="";if(text[i]==="{"){const b=readBraced(text,i);value=b.value;i=b.next;while(i<text.length&&text[i]!=="\n")i++;}else{const vs=i;while(i<text.length&&text[i]!=="\n"&&text[i]!=="\r")i++;value=text.slice(vs,i).trim();}if(key)out[key]=value;}return out;}
