  function normalizeJsonProfile(raw){const p0=raw&&raw.profile&&raw.profile.steps?raw.profile:raw;if(!p0||typeof p0!=="object")throw new Error("JSON does not contain a profile");const p=Object.assign({},p0);p.version=nonEmpty(p.version,"2");p.title=nonEmpty(p.title,p.reference_file||"");p.author=nonEmpty(p.author,"");p.notes=nonEmpty(p.notes,"");p.beverage_type=nonEmpty(p.beverage_type,"espresso");p.tank_temperature=n(p.tank_temperature!==undefined?p.tank_temperature:p.tank_desired_water_temperature,"0");p.target_weight=n(p.target_weight!==undefined?p.target_weight:p.final_desired_shot_weight_advanced,"0");p.target_volume=n(p.target_volume!==undefined?p.target_volume:p.final_desired_shot_volume_advanced,"0");p.target_volume_count_start=n(p.target_volume_count_start!==undefined?p.target_volume_count_start:p.final_desired_shot_volume_advanced_count_start,"0");if(!Array.isArray(p.steps)||!p.steps.length)throw new Error("Profile has no steps");if(!p.title)throw new Error("Profile has no title");return p;}
  async function createProfile(profile,meta){const r=await fetch(LOCAL_API+"/profiles",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({profile,metadata:meta||{}})});const t=await r.text();if(!r.ok)throw new Error("Decaid rejected profile (HTTP "+r.status+"): "+t.slice(0,280));let rec={};try{rec=JSON.parse(t);}catch(_){}return {success:true,title:profile.title,id:rec.id||null};}
  async function getDefaults(){try{const a=await fetchJson(LOCAL_API+"/profiles/defaults");if(!Array.isArray(a))return [];return a.map(x=>({kind:"default",id:"default:"+x.filename,filename:x.filename,title:x.title||niceName(x.filename),author:x.author||"",source:"Decaid bundled",format:"json",maintenance:maintenance((x.title||"")+" "+x.filename)}));}catch(e){log("defaults: "+e.message);return [];}}
