  async function refreshOnline(){const merged=COMMUNITY.map(x=>Object.assign({kind:"online",sourceId:"community",maintenance:maintenance(x.title)},x));const errors=[];for(const source of ONLINE_SOURCES){try{const list=await fetchJson(source.api);if(!Array.isArray(list))throw new Error("directory response is not an array");for(const it of list){const x=onlineItem(source,it);if(x)merged.push(x);}}catch(e){errors.push(source.label+": "+e.message);}}const seen=new Set(),out=[];for(const x of merged){const key=(x.sourceId||x.source)+"|"+(x.path||x.url||x.title);if(!seen.has(key)){seen.add(key);out.push(x);}}onlineCache=out;refreshInfo.online={at:new Date().toISOString(),count:out.length,errors};return refreshInfo.online;}
  function skinAssetUrl(id,path){return LOCAL_API+"/webui/skin-assets/"+encodeURIComponent(id)+"/"+path.split("/").map(encodeURIComponent).join("/");}
  async function refreshSkins(){const out=[],errors=[];let raw;try{raw=await fetchJson(LOCAL_API+"/webui/skins");}catch(e){refreshInfo.skins={at:new Date().toISOString(),count:0,errors:[e.message]};skinCache=[];return refreshInfo.skins;}const skins=Array.isArray(raw)?raw:(Array.isArray(raw.skins)?raw.skins:[]);const candidates=["profiles/manifest.json","profiles/index.json","assets/defaultProfiles/manifest.json","profiles.json"];for(const sk of skins){const id=sk.id||sk.skinId||sk.name;if(!id)continue;const label=sk.name||sk.title||id;for(const path of candidates){try{const data=await fetchJson(skinAssetUrl(id,path));let list=Array.isArray(data)?data:(Array.isArray(data.profiles)?data.profiles:[]);if(!list.length)continue;const dir=path.includes("/")?path.slice(0,path.lastIndexOf("/")+1):"";for(const z of list){const filename=typeof z==="string"?z:(z.filename||z.path||"");if(!filename||!/\.(json|tcl)$/i.test(filename))continue;const full=filename.includes("/")?filename:dir+filename;out.push({kind:"skin",id:"skin:"+id+":"+full,title:(typeof z==="object"&&z.title)||niceName(filename),author:(typeof z==="object"&&z.author)||"",source:"Installed skin · "+label,skinId:id,path:full,format:filename.toLowerCase().endsWith(".tcl")?"tcl":"json",maintenance:maintenance(filename)});}break;}catch(_){}}}skinCache=out;refreshInfo.skins={at:new Date().toISOString(),count:out.length,errors};return refreshInfo.skins;}
