  return {id:PLUGIN_ID,version:VERSION,onLoad:function(){log("loaded v"+VERSION)},onUnload:function(){log("unloaded")},onEvent:function(){},__httpRequestHandler:function(req){
    if(req.endpoint==="ui")return textResponse(200,"text/html; charset=utf-8",renderHtml());
    if(req.endpoint==="skin")return jsonResponse(200,{version:1,surfaces:[],settingsOpen:{type:"open",presentation:"overlay",closeOnShot:true}});
    if(req.endpoint==="catalog")return catalog().then(x=>jsonResponse(200,x)).catch(e=>jsonResponse(500,{error:e.message}));
    if(req.endpoint==="refresh"){if(req.method!=="POST")return jsonResponse(405,{error:"Method not allowed"});const b=bodyObject(req),scope=b.scope||"all";let job;if(scope==="online")job=refreshOnline();else if(scope==="skins")job=refreshSkins();else job=Promise.all([refreshOnline(),refreshSkins()]);return job.then(x=>jsonResponse(200,{success:true,result:x,refreshInfo})).catch(e=>jsonResponse(500,{error:e.message}));}
    if(req.endpoint==="import"){if(req.method!=="POST")return jsonResponse(405,{error:"Method not allowed"});const b=bodyObject(req);let job;if(b.kind==="default")job=importDefault(b.filename);else if(b.kind==="snapshot")job=importSnapshot(b.id);else if(b.kind==="online")job=importOnline(b.id);else if(b.kind==="skin")job=importSkin(b.id);else return jsonResponse(400,{error:"Invalid import request"});return job.then(x=>{log("imported "+x.title);return jsonResponse(200,x)}).catch(e=>{log("import failed: "+e.message);return jsonResponse(400,{error:e.message})});}
    return jsonResponse(404,{error:"Not found"});
  }};
